#!/usr/bin/env python3
"""Apply and close the complete Phase 2 card-profile stage."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content.replace('\r\n', '\n'), encoding='utf-8', newline='\n')

def read(path: str) -> str:
    return (ROOT / path).read_text(encoding='utf-8')

def replace_once(source: str, old: str, new: str, label: str) -> str:
    count = source.count(old)
    if count != 1:
        raise RuntimeError(f'{label}: expected one match, found {count}')
    return source.replace(old, new, 1)

MAJORS = [f'major-{n}' for n in range(22)]
RANKS = ['ace','two','three','four','five','six','seven','eight','nine','ten','page','knight','queen','king']
SUITS = ['wands','cups','swords','pentacles']
ALL_IDS = MAJORS + [f'{suit}-{rank}' for suit in SUITS for rank in RANKS]
GOLDEN = ['major-0','major-7','major-9','major-16','cups-two','pentacles-eight']
UPGRADE = [card_id for card_id in ALL_IDS if card_id not in GOLDEN]
