for card_id in UPGRADE:
    write(f'src/knowledge/cards/{card_id}.js', f'import {{ createCompleteCardProfile }} from "./create-complete-profile.js";\nexport const CARD_PROFILE = createCompleteCardProfile("{card_id}");\nexport default CARD_PROFILE;\n')

entries = '\n'.join(f'  "{card_id}": async () => (await import("./{card_id}.js")).CARD_PROFILE,' for card_id in ALL_IDS)
write('src/knowledge/cards/registry.js', f'export const GOLDEN_CARD_IDS = Object.freeze({json.dumps(GOLDEN)});\nexport const CARD_PROFILE_IDS = Object.freeze({json.dumps(ALL_IDS)});\nexport const CARD_PROFILE_REGISTRY = Object.freeze({{\n{entries}\n}});\nexport const GOLDEN_CARD_REGISTRY = Object.freeze(Object.fromEntries(GOLDEN_CARD_IDS.map((id)=>[id,CARD_PROFILE_REGISTRY[id]])));\nexport async function loadCardProfile(cardId){{const loader=CARD_PROFILE_REGISTRY[cardId];if(!loader)throw new Error(`Unknown card profile: ${{cardId}}`);return loader();}}\nexport async function loadGoldenCardProfile(cardId){{if(!GOLDEN_CARD_REGISTRY[cardId])throw new Error(`Unknown golden card profile: ${{cardId}}`);return loadCardProfile(cardId);}}\n')
write('src/knowledge/cards/phase-2-batches.js', 'export const PHASE_2_BATCHES = Object.freeze(' + json.dumps(BATCHES, ensure_ascii=False, indent=2) + ');\n')

golden_hashes={card_id:hashlib.sha256((ROOT/f'src/knowledge/cards/{card_id}.js').read_bytes().replace(b'\r\n',b'\n')).hexdigest() for card_id in GOLDEN}
write('tests/fixtures/phase-2/golden-profile-hashes.json', json.dumps(golden_hashes, indent=2)+'\n')

write('scripts/score_all_cards.mjs', r'''#!/usr/bin/env node
import fs from "node:fs";import path from "node:path";import {fileURLToPath} from "node:url";
import {CARD_PROFILE_IDS,GOLDEN_CARD_IDS,loadCardProfile} from "../src/knowledge/cards/registry.js";
import {PHASE_2_BATCHES} from "../src/knowledge/cards/phase-2-batches.js";
import {scoreCardProfile} from "../src/engine/validation/card-quality-gate.js";
import {QUESTION_CLASSIFICATIONS} from "../src/knowledge/questions/classification.js";
import {loadQuestionProfile} from "../src/knowledge/questions/registry.js";
import {POSITION_OPERATOR_GROUPS} from "../src/knowledge/spreads/operators/index.js";
import {createMinimalObservation} from "../src/engine/observations/minimal-consumer.js";
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");const schema=JSON.parse(fs.readFileSync(path.join(root,"src/knowledge/schemas/card-semantic-profile.schema.json"),"utf8"));const profiles=[];for(const id of CARD_PROFILE_IDS)profiles.push(await loadCardProfile(id));const cards=profiles.map((profile)=>scoreCardProfile(profile,schema));const questions=Object.fromEntries(["relationship","career","finance","growth","decision","daily"].map((domain)=>[domain,QUESTION_CLASSIFICATIONS.find((item)=>item.domain===domain).id]));const operators=Object.values(POSITION_OPERATOR_GROUPS).flat();let total=0,passed=0;const failures=[];for(const card of profiles)for(const [domain,questionId] of Object.entries(questions)){const question=await loadQuestionProfile(questionId);for(const operator of operators)for(const orientation of ["upright","reversed"]){total++;try{const observation=createMinimalObservation({card,question,operator,orientation,reversalMode:orientation==="reversed"?card.reversal.supportedModes[0]:null});if(!observation.semanticUnitRef.startsWith(`${card.id}#`)||!Number.isFinite(observation.localScore))throw new Error("invalid observation");passed++;}catch(error){if(failures.length<50)failures.push({cardId:card.id,domain,spreadId:operator.spreadId,positionId:operator.positionId,orientation,message:String(error.message||error)});}}}const seen=new Map(),duplicates=[];for(const card of profiles)for(const unit of Object.values(card.facets).flat()){const value=unit.text.trim(),owner=seen.get(value);if(owner&&owner!==card.id)duplicates.push({text:value,owners:[owner,card.id]});else seen.set(value,card.id);}const upgraded=CARD_PROFILE_IDS.filter((id)=>!GOLDEN_CARD_IDS.includes(id)),covered=new Set(Object.values(PHASE_2_BATCHES).flat());const report={schemaVersion:"1.0.0",scope:"phase-2-development-quality-and-cross-review",generatedAt:"2026-07-31",cards,summary:{count:cards.length,minimum:Math.min(...cards.map((x)=>x.score)),average:Number((cards.reduce((s,x)=>s+x.score,0)/cards.length).toFixed(2)),admitted:cards.filter((x)=>x.admitted).length,schemaPassRate:Number((cards.filter((x)=>x.schemaErrors.length===0).length/cards.length).toFixed(4)),scenarioPassRate:Number((passed/total).toFixed(4)),scenarioPassed:passed,scenarioTotal:total},crossReview:{duplicateSemanticTexts:duplicates,batchCount:Object.keys(PHASE_2_BATCHES).length,batchCoverageComplete:upgraded.every((id)=>covered.has(id))&&covered.size===upgraded.length,goldenCardCount:GOLDEN_CARD_IDS.length,upgradedCardCount:upgraded.length},scenarioFailures:failures};const text=`${JSON.stringify(report,null,2)}\n`,target=path.join(root,".qa/card-profile-report.json");if(process.argv.includes("--write")){fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,text,"utf8");}else if(process.argv.includes("--check")){if(fs.readFileSync(target,"utf8").replace(/\r\n?/g,"\n")!==text){console.error("Phase 2 card profile report is stale.");process.exitCode=1;}}console.log(JSON.stringify(report.summary));
''')

write('tests/phase_2_golden_freeze_test.mjs', r'''import assert from "node:assert/strict";import crypto from "node:crypto";import fs from "node:fs";import path from "node:path";import {fileURLToPath} from "node:url";const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");const expected=JSON.parse(fs.readFileSync(path.join(root,"tests/fixtures/phase-2/golden-profile-hashes.json"),"utf8"));for(const [id,digest] of Object.entries(expected)){const text=fs.readFileSync(path.join(root,`src/knowledge/cards/${id}.js`),"utf8").replace(/\r\n?/g,"\n");assert.equal(crypto.createHash("sha256").update(text).digest("hex"),digest,`${id} golden profile changed`);}console.log("Phase 2 golden profile freeze passed.");
''')
write('tests/phase_2_card_profiles_test.mjs', r'''import assert from "node:assert/strict";import fs from "node:fs";import path from "node:path";import {fileURLToPath} from "node:url";import {TarotData} from "../src/knowledge/legacy/index.js";import {CARD_PROFILE_IDS,GOLDEN_CARD_IDS,loadCardProfile} from "../src/knowledge/cards/registry.js";import {PHASE_2_BATCHES} from "../src/knowledge/cards/phase-2-batches.js";import {scoreCardProfile} from "../src/engine/validation/card-quality-gate.js";const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");const schema=JSON.parse(fs.readFileSync(path.join(root,"src/knowledge/schemas/card-semantic-profile.schema.json"),"utf8"));assert.deepEqual(CARD_PROFILE_IDS,TarotData.deck.map((card)=>card.id));assert.equal(CARD_PROFILE_IDS.length,78);const batchIds=Object.values(PHASE_2_BATCHES).flat();assert.equal(Object.keys(PHASE_2_BATCHES).length,16);assert.equal(batchIds.length,72);assert.equal(new Set(batchIds).size,72);assert.deepEqual(CARD_PROFILE_IDS.filter((id)=>!GOLDEN_CARD_IDS.includes(id)).sort(),[...batchIds].sort());for(const id of CARD_PROFILE_IDS){const profile=await loadCardProfile(id),result=scoreCardProfile(profile,schema);assert.equal(profile.id,id);assert.equal(result.admitted,true,`${id}: ${JSON.stringify(result)}`);assert.ok(result.score>=90);assert.equal(result.schemaErrors.length,0);assert.equal(result.vocabularyErrors.length,0);}const report=JSON.parse(fs.readFileSync(path.join(root,".qa/card-profile-report.json"),"utf8"));assert.equal(report.summary.count,78);assert.ok(report.summary.minimum>=90);assert.ok(report.summary.average>=92);assert.equal(report.summary.schemaPassRate,1);assert.ok(report.summary.scenarioPassRate>=.95);assert.equal(report.crossReview.duplicateSemanticTexts.length,0);assert.equal(report.crossReview.batchCoverageComplete,true);console.log("Phase 2 profile contract passed.");
''')
write('tests/phase_2_gate_test.mjs', r'''import assert from "node:assert/strict";import fs from "node:fs";import path from "node:path";import {fileURLToPath} from "node:url";import {CARD_PROFILE_IDS,loadCardProfile} from "../src/knowledge/cards/registry.js";const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"..");const report=JSON.parse(fs.readFileSync(path.join(root,".qa/card-profile-report.json"),"utf8")),progress=fs.readFileSync(path.join(root,"docs/PROGRESS.md"),"utf8");assert.match(progress,/Phase 2状态 \| `PARENT-DONE`/);assert.match(progress,/唯一下一任务 \| `QP-003A`/);assert.equal(report.summary.admitted,78);assert.ok(report.summary.minimum>=90&&report.summary.average>=92);assert.equal(report.summary.schemaPassRate,1);assert.ok(report.summary.scenarioPassRate>=.95);assert.equal(report.crossReview.duplicateSemanticTexts.length,0);for(const id of CARD_PROFILE_IDS)assert.equal((await loadCardProfile(id)).id,id);assert.equal(fs.existsSync(path.join(root,"automation/phase_2_apply.py")),false);console.log("Phase 2 terminal gate passed.");
''')

